/*
 * deer-sprite.js — 그림 한 장으로 움직이는 사슴 (WebGL 메시 변형)
 *
 * 사용법:
 *   <canvas id="deer" style="width:300px; aspect-ratio:880/1000"></canvas>
 *   <script src="deer-sprite.js"></script>
 *   <script>
 *     const deer = DeerSprite.create(document.getElementById("deer"));
 *     deer.nod();            // 고개 꾸벅 (클릭 반응 등에 연결). deer.nod(1.5) 처럼 세기 조절 가능
 *     deer.attachToHead(el, 190, 205); // el(모자 등)이 머리를 따라다님. 숫자는 그림 좌표(640x928)
 *     deer.showMesh(true);   // 격자 보기 (디버그용)
 *     deer.destroy();        // 정리
 *   </script>
 *
 * 옵션: DeerSprite.create(canvas, {
 *   src: "deer.png",   // 다른 그림 경로 (생략하면 파일 안에 든 사슴 그림 사용)
 *   nodAngle: -0.26,   // 숙이는 각도(라디안). 음수 = 앞으로 숙임
 *   breath: 0.012,     // 숨쉬기 세기
 *   tailWag: 0.32,     // 꼬리 흔들기 세기
 *   bounce: 1.1,       // 클릭 시 통통 튀는 세기 (0이면 없음)
 *   pad: 0             // 그림 둘레 여백(px). 모자·망토처럼 몸 밖으로 튀어나온 스킨용
 * })
 * deer.setSrc("assets/skins/helmet.png", 100); // 그림(스킨) 바꾸기 (여백 100px 그림)
 * 캔버스 비율은 880:1000 으로 맞춰주세요. 배경은 투명이에요.
 */
(function (root) {
  "use strict";

  var DEFAULT_SRC =
    "data:image/webp;base64,";

  // 그림 좌표(640 x 928) 기준 값들. 다른 그림으로 바꾸면 여기를 조정하세요.
  var IMG_W = 640,
    IMG_H = 928;
  var WORLD_W = 880,
    WORLD_H = 1000,
    OFF_X = 150,
    OFF_Y = 40; // 고개를 숙여도 안 잘리게 여백
  var PIVOT_HEAD = [205, 365]; // 목 윗부분: 머리가 도는 축
  var PIVOT_NECK = [195, 500]; // 목 아래: 목이 살짝 기우는 축
  var PIVOT_TAIL = [560, 455]; // 꼬리 뿌리
  var FEET_Y = 915; // 발바닥 높이 (통통 튈 때 기준선)

  var VS = [
    "attribute vec2 a_uv;",
    "uniform vec2 u_img, u_world, u_off, u_ph, u_pn, u_pt, u_pad;",
    "uniform float u_head, u_tail, u_breath, u_sq, u_feet;",
    "varying vec2 v_uv; varying vec3 v_w;",
    "vec2 rot(vec2 p, vec2 c, float a){ vec2 d=p-c; float s=sin(a), k=cos(a); return c+vec2(d.x*k-d.y*s, d.x*s+d.y*k); }",
    "void main(){",
    "  vec2 p = a_uv * (u_img + 2.0 * u_pad) - u_pad;", // 여백 있는 그림이면 여백만큼 빼서 원래 좌표로
    // 가중치: 각 점이 부위를 얼마나 따라갈지 (0~1)
    "  float xmask = 1.0 - smoothstep(250.0, 300.0, p.x);",
    "  float wh = (1.0 - smoothstep(345.0, 380.0, p.y)) * mix(1.0, xmask, smoothstep(320.0, 350.0, p.y));",
    "  float wn = (1.0 - smoothstep(400.0, 500.0, p.y)) * mix(1.0, xmask, smoothstep(330.0, 370.0, p.y));",
    "  float wt = smoothstep(540.0, 578.0, p.x) * (1.0 - smoothstep(492.0, 522.0, p.y));",
    "  float wb = 1.0 - smoothstep(560.0, 740.0, p.y);",
    "  v_w = vec3(max(wh, wn * 0.55), wt, wb);",
    "  p.y = 620.0 + (p.y - 620.0) * (1.0 + u_breath * wb);", // 숨쉬기
    "  p = rot(p, u_ph, u_head * wh);", // 머리
    "  p = rot(p, u_pn, u_head * 0.4 * wn);", // 목
    "  p = rot(p, u_pt, u_tail * wt);", // 꼬리
    "  p.y = u_feet + (p.y - u_feet) * u_sq;", // 통통
    "  p.x = 320.0 + (p.x - 320.0) * (2.0 - u_sq);",
    "  vec2 w = (p + u_off) / u_world;",
    "  gl_Position = vec4(w.x * 2.0 - 1.0, 1.0 - w.y * 2.0, 0.0, 1.0);",
    "  v_uv = a_uv;",
    "}",
  ].join("\n");

  var FS = [
    "precision mediump float;",
    "uniform sampler2D u_tex; uniform int u_mode;",
    "varying vec2 v_uv; varying vec3 v_w;",
    "void main(){",
    "  if (u_mode == 0) { gl_FragColor = texture2D(u_tex, v_uv); return; }",
    "  vec3 c = vec3(0.55, 0.6, 0.55);",
    "  c = mix(c, vec3(0.88, 0.69, 0.23), v_w.z * 0.6);",
    "  c = mix(c, vec3(0.23, 0.5, 0.88), v_w.y);",
    "  c = mix(c, vec3(0.88, 0.34, 0.23), v_w.x);",
    "  gl_FragColor = vec4(c * 0.55, 0.55);",
    "}",
  ].join("\n");

  function create(canvas, opts) {
    opts = opts || {};
    var o = {
      src: opts.src || DEFAULT_SRC,
      nodAngle: opts.nodAngle != null ? opts.nodAngle : -0.26,
      breath: opts.breath != null ? opts.breath : 0.012,
      tailWag: opts.tailWag != null ? opts.tailWag : 0.32,
      bounce: opts.bounce != null ? opts.bounce : 1.1,
      pad: opts.pad || 0,
    };

    var gl = canvas.getContext("webgl", {
      premultipliedAlpha: true,
      alpha: true,
      antialias: true,
    });
    if (!gl)
      throw new Error("DeerSprite: 이 브라우저는 WebGL을 지원하지 않아요.");

    function sh(type, src) {
      var s = gl.createShader(type);
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
        throw new Error(gl.getShaderInfoLog(s));
      return s;
    }
    var prog = gl.createProgram();
    gl.attachShader(prog, sh(gl.VERTEX_SHADER, VS));
    gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FS));
    gl.linkProgram(prog);
    gl.useProgram(prog);
    var U = function (n) {
      return gl.getUniformLocation(prog, n);
    };

    // 격자 메시
    var GX = 44,
      GY = 64,
      uv = [],
      tri = [],
      lines = [];
    for (var y = 0; y <= GY; y++)
      for (var x = 0; x <= GX; x++) uv.push(x / GX, y / GY);
    var idx = function (x, y) {
      return y * (GX + 1) + x;
    };
    for (y = 0; y < GY; y++)
      for (x = 0; x < GX; x++)
        tri.push(
          idx(x, y),
          idx(x + 1, y),
          idx(x, y + 1),
          idx(x + 1, y),
          idx(x + 1, y + 1),
          idx(x, y + 1),
        );
    for (y = 0; y <= GY; y += 2)
      for (x = 0; x < GX; x++) lines.push(idx(x, y), idx(x + 1, y));
    for (x = 0; x <= GX; x += 2)
      for (y = 0; y < GY; y++) lines.push(idx(x, y), idx(x, y + 1));

    var vb = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, vb);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(uv), gl.STATIC_DRAW);
    var loc = gl.getAttribLocation(prog, "a_uv");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    var tb = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, tb);
    gl.bufferData(
      gl.ELEMENT_ARRAY_BUFFER,
      new Uint16Array(tri),
      gl.STATIC_DRAW,
    );
    var lb = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, lb);
    gl.bufferData(
      gl.ELEMENT_ARRAY_BUFFER,
      new Uint16Array(lines),
      gl.STATIC_DRAW,
    );

    gl.uniform2f(U("u_img"), IMG_W, IMG_H);
    gl.uniform2f(U("u_pad"), o.pad, o.pad);
    gl.uniform2f(U("u_world"), WORLD_W, WORLD_H);
    gl.uniform2f(U("u_off"), OFF_X, OFF_Y);
    gl.uniform2f(U("u_ph"), PIVOT_HEAD[0], PIVOT_HEAD[1]);
    gl.uniform2f(U("u_pn"), PIVOT_NECK[0], PIVOT_NECK[1]);
    gl.uniform2f(U("u_pt"), PIVOT_TAIL[0], PIVOT_TAIL[1]);
    gl.uniform1f(U("u_feet"), FEET_Y);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

    var tex = gl.createTexture(),
      ready = false;

    // 그림 불러와서 텍스처로 올리기 (처음 + setSrc 로 스킨 바꿀 때)
    function loadSrc(src, pad) {
      var img = new Image();
      if (!/^data:/.test(src) && /^https?:/.test(src)) img.crossOrigin = "anonymous";
      img.onload = function () {
        upload(img);
        gl.uniform2f(U("u_pad"), pad, pad);
      };
      img.src = src;
    }
    function upload(img) {
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, true);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      ready = true;
    }
    loadSrc(o.src, o.pad);

    function resize() {
      var r = canvas.getBoundingClientRect(),
        d = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.round(r.width * d));
      canvas.height = Math.max(1, Math.round(r.height * d));
      gl.viewport(0, 0, canvas.width, canvas.height);
    }
    var ro = new ResizeObserver(resize);
    ro.observe(canvas);
    resize();

    // 스프링: 값이 목표를 쫓아가며 출렁임
    var head = { v: 0, vel: 0, target: 0 },
      squash = { v: 1, vel: 0, target: 1 };
    function step(s, k, c, dt) {
      var a = -k * (s.v - s.target) - c * s.vel;
      s.vel += a * dt;
      s.v += s.vel * dt;
    }

    var reduce =
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    var attached = [];
    var cur = { a: 0, b: 0, sq: 1 };
    function rotPt(x, y, c, a) {
      var dx = x - c[0],
        dy = y - c[1],
        s = Math.sin(a),
        k = Math.cos(a);
      return [c[0] + dx * k - dy * s, c[1] + dx * s + dy * k];
    }
    // 셰이더와 같은 계산으로 머리 위 한 점이 지금 어디 있는지 구함 (머리 영역 안의 점만 정확)
    function headPoint(px, py) {
      var y = 620 + (py - 620) * (1 + cur.b);
      var p = rotPt(px, y, PIVOT_HEAD, cur.a);
      p = rotPt(p[0], p[1], PIVOT_NECK, cur.a * 0.4);
      p[1] = FEET_Y + (p[1] - FEET_Y) * cur.sq;
      p[0] = 320 + (p[0] - 320) * (2 - cur.sq);
      return [(p[0] + OFF_X) / WORLD_W, (p[1] + OFF_Y) / WORLD_H];
    }
    function placeAttached() {
      for (var i = 0; i < attached.length; i++) {
        var it = attached[i],
          q = headPoint(it.x, it.y);
        it.el.style.left = canvas.offsetLeft + q[0] * canvas.offsetWidth + "px";
        it.el.style.top = canvas.offsetTop + q[1] * canvas.offsetHeight + "px";
        it.el.style.transform =
          "translate(-50%, -100%) rotate(" + (cur.a * 1.4).toFixed(3) + "rad)";
      }
    }

    var mesh = false,
      last = performance.now(),
      t0 = last,
      nodTimer = 0,
      wagUntil = 0,
      nextWag = 1.5,
      raf = 0,
      alive = true;

    function frame(now) {
      if (!alive) return;
      var dt = Math.min(0.033, (now - last) / 1000);
      last = now;
      var t = (now - t0) / 1000;
      if (nodTimer > 0) {
        nodTimer -= dt;
        if (nodTimer <= 0) head.target = 0;
      }
      step(head, 200, 22, dt);
      step(squash, 420, 18, dt);

      if (t > nextWag) {
        wagUntil = t + 1.2;
        nextWag = t + 2.5 + Math.random() * 2.5;
      }
      var wag =
        t < wagUntil ? Math.sin(Math.PI * (1 - (wagUntil - t) / 1.2)) : 0;
      var m = reduce ? 0.3 : 1;

      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      cur.a = head.v + Math.sin(t * 1.3) * 0.025 * m;
      cur.b = Math.sin(t * 2.2) * o.breath * m;
      cur.sq = squash.v;
      placeAttached();
      if (ready) {
        gl.uniform1f(U("u_head"), cur.a);
        gl.uniform1f(
          U("u_tail"),
          (Math.sin(t * 18) * o.tailWag * wag + Math.sin(t * 1.1) * 0.04) * m,
        );
        gl.uniform1f(U("u_breath"), cur.b);
        gl.uniform1f(U("u_sq"), squash.v);
        gl.uniform1i(U("u_mode"), 0);
        gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, tb);
        gl.drawElements(gl.TRIANGLES, tri.length, gl.UNSIGNED_SHORT, 0);
        if (mesh) {
          gl.uniform1i(U("u_mode"), 1);
          gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, lb);
          gl.drawElements(gl.LINES, lines.length, gl.UNSIGNED_SHORT, 0);
        }
      }
      raf = requestAnimationFrame(frame);
    }
    raf = requestAnimationFrame(frame);

    return {
      /** 고개를 꾸벅 숙였다가 돌아와요 */
      nod: function (strength) {
        var s = strength == null ? 1 : strength;
        head.target = o.nodAngle * s;
        nodTimer = 0.18;
        squash.vel -= o.bounce * s;
      },
      /** el 을 머리 위 (x, y) 지점에 붙여서 같이 움직이게 함. el 은 캔버스와 같은 부모 안에 position:absolute 로 */
      attachToHead: function (el, x, y) {
        attached.push({ el: el, x: x, y: y });
        placeAttached();
      },
      /** 그림 바꾸기 (스킨). src 를 비우면 기본 사슴, pad 는 그림 둘레 여백(px) */
      setSrc: function (src, pad) {
        loadSrc(src || DEFAULT_SRC, src ? pad || 0 : 0);
      },
      /** 꼬리를 지금 바로 흔들어요 */
      wag: function () {
        var t = (performance.now() - t0) / 1000;
        wagUntil = t + 1.2;
        nextWag = t + 3;
      },
      /** 격자(가중치) 표시 켜기/끄기 */
      showMesh: function (on) {
        mesh = !!on;
      },
      /** 애니메이션 멈추고 정리 */
      destroy: function () {
        alive = false;
        cancelAnimationFrame(raf);
        ro.disconnect();
        var ext = gl.getExtension("WEBGL_lose_context");
        if (ext) ext.loseContext();
      },
    };
  }

  var api = { create: create };
  if (typeof module === "object" && module.exports) module.exports = api;
  root.DeerSprite = api;
})(typeof window !== "undefined" ? window : this);
